package dev.pocketengine;
import dev.pocketengine.core.CapabilityPort;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.features.NativePluginHost;
import dev.pocketengine.features.plugins.catalog.PluginCatalogSession;
import java.lang.reflect.Field;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=EngineApplication.class)
public final class NativePluginApplicationHostTest {
 private EngineApplication app(){return (EngineApplication)RuntimeEnvironment.getApplication();}
 private static Object field(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 @SuppressWarnings("unchecked") private RunControl admit(EngineApplication app,JSONObject task)throws Exception{RunControl c=new RunControl();c.bindHostRun(task.getString("id"),task.getString("runId"),task.getInt("coordinatorEpoch"));((ConcurrentHashMap<String,RunControl>)field(app,"capabilityControls")).put(task.getString("id"),c);return c;}
 private PluginCatalogSession.View execute(NativePluginHost.Page p,PluginCatalogSession.Request req)throws Exception{p.beforeDispatch(req,p.session.view(p.nativeOwner()),new JSONObject());PluginCatalogSession.View v=req.execute();p.settled(req,v,req.receipt());return v;}
 @Test public void actualAppUsesOneCatalogStoreAndSandboxAndOnlyOriginalControlGetsTheFinalW08OuterPort()throws Exception{
  EngineApplication a=app();assertSame(a.tasks,field(a.pluginHost,"tasks"));assertSame(a.features.module("plugins"),field(a.pluginHost,"plugins"));assertSame(a.pluginHost.sharedSandbox(),field(a.pluginHost,"sandbox"));assertEquals("not_prepared",a.pluginHost.runtimeSnapshot().getString("status"));
  JSONObject t=a.tasks.startAttempt(a.tasks.createCapabilityTask("native integration","").getString("id"),"capabilities",10);String id=t.getString("id");RunControl c=admit(a,t);RunControl foreign=new RunControl();foreign.bindHostRun(id,t.getString("runId"),t.getInt("coordinatorEpoch"));assertThrows(SecurityException.class,()->a.capabilitiesForTask(id,foreign));
  CapabilityPort legacy=a.capabilitiesForTask(id);assertFalse(legacy.supports("attachments_create_text"));
  CapabilityPort one=a.capabilitiesForTask(id,c);assertEquals("dev.pocketengine.runtime.extensions.ExtensionCapabilityPort",one.getClass().getName());assertTrue(one.supports("attachments_create_text"));assertTrue(one.supports("attachments_read_document"));assertFalse(one.supports("browser_navigate"));assertFalse(one.supports("ssh_exec"));one.beginRun("native integration",c);Object source=field(((ConcurrentHashMap<?,?>)field(a.pluginHost,"runs")).get(c),"source");one.close();c.pause();assertThrows(SecurityException.class,()->a.capabilitiesForTask(id,c));c.resume();CapabilityPort resumed=a.capabilitiesForTask(id,c);resumed.beginRun("same original run",c);assertSame(source,field(((ConcurrentHashMap<?,?>)field(a.pluginHost,"runs")).get(c),"source"));resumed.close();a.pluginHost.release(id,c);assertTrue(((ConcurrentHashMap<?,?>)field(a.pluginHost,"runs")).isEmpty());assertEquals("not_prepared",a.pluginHost.runtimeSnapshot().getString("status"));
 }
 @Test public void catalogIntentExistsBeforeConfigureAndOriginalReceiptSurvivesNavigation()throws Exception{
  EngineApplication a=app();NativePluginHost.Page p=a.pluginHost.newOwnerPage();JSONObject config=execute(p,p.session.begin(p.nativeOwner(),UUID.randomUUID().toString(),"read",new JSONObject())).data().getJSONObject("config");String request=UUID.randomUUID().toString();PluginCatalogSession.Request write=p.session.begin(p.nativeOwner(),request,"configure",new JSONObject().put("sources",new JSONArray()).put("expectedRevision",config.getString("revision")));PluginCatalogSession.View pending=p.session.view(p.nativeOwner());p.beforeDispatch(write,pending,new JSONObject());JSONObject before=a.tasks.get(request,false);assertEquals(1,before.getJSONArray("operations").length());assertEquals("prepared",before.getJSONArray("operations").getJSONObject(0).getString("state"));assertEquals(pending.pageRequestId,before.getJSONArray("operations").getJSONObject(0).getJSONObject("arguments").getString("pageRequestId"));
  PluginCatalogSession.View result=write.execute();JSONObject actual=write.receipt();assertNotNull(actual);p.close();p.settled(write,result,actual);JSONObject retained=a.tasks.get(request,false).getJSONArray("operations").getJSONObject(0);assertEquals("receipt",retained.getString("state"));assertEquals(actual.getString("revision"),retained.getJSONObject("receipt").getString("revision"));assertFalse(p.session.accepts(p.nativeOwner(),result));assertThrows(SecurityException.class,()->p.beforeDispatch(write,pending,new JSONObject()));
 }
 @Test public void writeWithoutAnActualReceiptIsUnknownAndCannotBeResubmittedFromAnAbandonedPage()throws Exception{
  EngineApplication a=app();NativePluginHost.Page p=a.pluginHost.newOwnerPage();JSONObject config=execute(p,p.session.begin(p.nativeOwner(),UUID.randomUUID().toString(),"read",new JSONObject())).data().getJSONObject("config");String request=UUID.randomUUID().toString();PluginCatalogSession.Request write=p.session.begin(p.nativeOwner(),request,"configure",new JSONObject().put("sources",new JSONArray()).put("expectedRevision",config.getString("revision")));p.beforeDispatch(write,p.session.view(p.nativeOwner()),new JSONObject());p.close();PluginCatalogSession.View result=write.execute();assertNull(write.receipt());p.settled(write,result,null);JSONObject task=a.tasks.get(request,false);assertEquals("unknown",task.getJSONArray("operations").getJSONObject(0).getString("state"));assertTrue(a.tasks.hasUnresolved(request));assertEquals("reconciling",task.getString("status"));assertThrows(IllegalStateException.class,write::execute);
 }
 @Test public void actualAppW08CreatesRealBytesAndTypedDocumentAndOriginalReceiptSurvivesStop()throws Exception{
  EngineApplication a=app();JSONObject t=a.tasks.startAttempt(a.tasks.createCapabilityTask("create a retained text attachment","").getString("id"),"capabilities",10);String id=t.getString("id"),run=t.getString("runId");RunControl c=admit(a,t);CapabilityPort port=a.capabilitiesForTask(id,c);port.beginRun(t.getString("goal"),c);port.prepareTurn(t.getString("goal"),0,0,c);
  JSONObject args=new JSONObject().put("name","native-receipt.txt").put("mimeType","text/plain").put("content","retained native bytes");JSONObject capability=new JSONObject().put("feature","attachments").put("command","createText").put("hostTaskId",id).put("projectId","");JSONObject pending=a.tasks.requireCapabilityApproval(id,run,"attachments_create_text",args,capability);a.tasks.decideCapabilityApproval(id,pending.getString("approvalId"),true);port.validate("attachments_create_text",args);assertNull(port.beforeTool("attachments_create_text",args,c));var journal=a.tasks.journal(id,run,t.getInt("coordinatorEpoch"),c);String operation=journal.beginOperation("attachments_create_text",args);JSONObject receipt=port.execute("attachments_create_text",new JSONObject(args.toString()).put("_hostOperationId",operation),c);assertEquals("created",receipt.getString("status"));c.cancel();journal.finishOperation(operation,receipt);JSONObject durable=a.tasks.get(id,false).getJSONArray("operations").getJSONObject(0);assertEquals("receipt",durable.getString("state"));assertEquals(receipt.getJSONObject("data").getString("id"),durable.getJSONObject("receipt").getJSONObject("data").getString("id"));assertEquals("retained native bytes",a.features.module("attachments").handle("readText",new JSONObject().put("id",receipt.getJSONObject("data").getString("id"))).getString("text"));assertFalse(a.tasks.hasUnresolved(id));port.close();a.pluginHost.release(id,c);
  JSONObject readTask=a.tasks.startAttempt(a.tasks.createCapabilityTask("read the actual attachment","").getString("id"),"capabilities",5);RunControl reader=admit(a,readTask);CapabilityPort read=a.capabilitiesForTask(readTask.getString("id"),reader);read.beginRun("read attachment",reader);read.prepareTurn("read attachment",0,0,reader);JSONObject query=new JSONObject().put("attachmentId",receipt.getJSONObject("data").getString("id")).put("expectedSha256",receipt.getJSONObject("data").getString("sha256"));read.validate("attachments_read_document",query);assertNull(read.beforeTool("attachments_read_document",query,reader));JSONObject document=read.execute("attachments_read_document",query,reader);assertTrue(document.toString(),document.toString().contains("retained native bytes"));assertFalse(document.optBoolean("verifiedBusinessSuccess"));read.close();a.pluginHost.release(readTask.getString("id"),reader);
 }
 @Test public void warmupCannotConnectOnMainOrTreatAnOpaquePageReadAsExecutableApproval()throws Exception{
  EngineApplication a=app();assertThrows(IllegalStateException.class,()->a.pluginHost.warm());NativePluginHost.Page p=a.pluginHost.newOwnerPage();execute(p,p.session.begin(p.nativeOwner(),UUID.randomUUID().toString(),"read",new JSONObject()));assertEquals(0,a.tasks.list().length());assertEquals("not_prepared",a.pluginHost.runtimeSnapshot().getString("status"));p.close();
 }
}
